import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    nums = data[1:1 + n] if n > 0 else []
    prod = 1
    has_even = False
    for token in nums:
        val = int(token)
        if val % 2 == 0:
            prod *= val
            has_even = True
    if not has_even:
        prod = 0
    sys.stdout.write(str(prod))

if __name__ == "__main__":
    solve()
